using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Net;
using System.Web.Script.Serialization;
using RestBuddy;
internal static class Checks {
  private static readonly List<string> passed=new List<string>(),failed=new List<string>();
  private static readonly DateTime start=new DateTime(2026,10,27,1,0,0,DateTimeKind.Utc);
  private static void Check(string name,Action action){try{action();passed.Add(name);}catch(Exception e){failed.Add(name+": "+e.GetType().Name+" "+e.Message);}}
  private static void Assert(bool value,string detail){if(!value)throw new Exception(detail);}
  private static Options Only(params string[] keys){Options o=new Options();foreach(Rule r in o.Rules)r.Enabled=keys.Contains(r.Key);return o;}
  private static void Advance(CareEngine engine,int minutes){for(int i=0;i<minutes*12;i++)engine.AddActive(5);}
  [STAThread]public static int Main(string[] args){
    if(args.Contains("--ui")){Native.SetProcessDPIAware();System.Windows.Forms.Application.EnableVisualStyles();System.Windows.Forms.Application.SetCompatibleTextRenderingDefault(false);Speech preview=null;string text="长文案阅读检查\n\n"+String.Join("\n\n",Enumerable.Range(1,24).Select(n=>"第 "+n+" 段：给眼睛一点远方，给自己一点余地。文字需要完整换行，内容较长时可以滚动阅读。"))+"\n\n【长文案末尾】这一行应该可以滚动看到。";preview=new Speech(null,text,"长文案布局检查",new[]{new SpeechAction("一起做一下","done"),new SpeechAction("刚休息过","rested"),new SpeechAction("现在忙","busy")},a=>preview.Close(),300000);preview.ShowInTaskbar=true;System.Windows.Forms.Application.Run(preview);return 0;}
    string folder=args[0];Directory.CreateDirectory(folder);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
    Check("health_has_four_groups",()=>Assert(new Options().Rules.Count==4,"topic count"));
    Check("random_primary_varies_across_seeds",()=>{var seen=new HashSet<string>();for(int seed=0;seed<60;seed++){CareEngine e=new CareEngine(Only("posture","rest","water"),new Random(seed),start);Advance(e,100);var rules=e.Suggest(start.AddMinutes(100));seen.Add(rules[0].Key);Assert(rules.Count==1,"combined reminder remained");}Assert(seen.Count==3,"primary always selected the same group");});
    Check("primary_avoids_repeat_when_alternatives_due",()=>{for(int seed=0;seed<30;seed++){Options o=Only("posture","rest","water");foreach(Rule r in o.Rules)r.Minutes=1;CareEngine e=new CareEngine(o,new Random(seed),start);Advance(e,5);string first=e.Suggest(start.AddMinutes(5))[0].Key;Advance(e,30);Assert(e.Suggest(start.AddMinutes(35))[0].Key!=first,"avoidable consecutive repeat");}});
    Check("action_variants_do_not_repeat",()=>{CareActionPicker p=new CareActionPicker(new Random(1));foreach(string key in new[]{"eyes","posture","rest"}){string last="";for(int i=0;i<30;i++){CareAction a=p.Next(key);Assert(a!=null&&a.Key==key&&a.Id!=last&&a.Seconds==Coach.DurationSeconds(key),"variant or duration mismatch");last=a.Id;}}});
    Check("manual_practice_varies_enabled_groups",()=>{CareActionPicker p=new CareActionPicker(new Random(1));string last="";var seen=new HashSet<string>();for(int i=0;i<30;i++){CareAction a=p.NextPractice(new Options().Rules);Assert(a.Key!=last&&a.Key!="water","practice stuck on one group");last=a.Key;seen.Add(a.Key);}Assert(seen.Count==3,"practice missing groups");});
    Check("manual_practice_respects_disabled_groups",()=>{CareActionPicker p=new CareActionPicker(new Random(1));for(int i=0;i<10;i++)Assert(p.NextPractice(Only("posture").Rules).Key=="posture","disabled practice selected");Assert(p.NextPractice(Only("water").Rules)==null,"no enabled exercise fallback");});
    Check("legacy_groups_migrate",()=>{Options o=new Options{Version=5};o.Rules=new List<Rule>{new Rule("eyes","", "",25,true),new Rule("blink","","",15,true),new Rule("posture","","",35,false),new Rule("hands","","",40,true),new Rule("feet","","",50,false),new Rule("stretch","","",60,true),new Rule("rest","","",80,false),new Rule("walk","","",45,true),new Rule("water","","",55,true),new Rule("toilet","","",120,true)};o.CustomMessages["hands"]="手部旧文案";o.CustomMessages["feet"]="支撑旧文案";o.CustomMessages["toilet"]="应移除的旧文案";CareCatalog.Normalize(o);Assert(o.Rules.Count==4&&!o.Rules.Any(r=>r.Key=="toilet"),"removed group remained");Assert(o.Rules.First(r=>r.Key=="eyes").Minutes==25&&o.Rules.First(r=>r.Key=="posture").Minutes==40&&o.Rules.First(r=>r.Key=="rest").Minutes==45,"legacy interval preference lost");Assert(o.CustomMessages["posture"].Contains("手部旧文案")&&o.CustomMessages["posture"].Contains("支撑旧文案")&&!o.CustomMessages.ContainsKey("toilet"),"custom wording migration");});
    Check("disabled_legacy_groups_remain_disabled",()=>{Options o=new Options();o.Rules=new List<Rule>{new Rule("eyes","","",20,false),new Rule("blink","","",15,false),new Rule("toilet","","",120,true)};CareCatalog.Normalize(o);Assert(o.Rules.All(r=>!r.Enabled),"migration enabled unrelated groups");});
    Check("migration_idempotent",()=>{Options o=new Options();o.Rules.Add(new Rule("hands","","",40,true));o.CustomMessages["hands"]="旧文案";CareCatalog.Normalize(o);string once=Store.Json.Serialize(o.Rules)+Store.Json.Serialize(o.CustomMessages);CareCatalog.Normalize(o);Assert(once==Store.Json.Serialize(o.Rules)+Store.Json.Serialize(o.CustomMessages),"migration repeats or changes settings");});
    Check("rest_completion_updates_related_groups",()=>{CareEngine e=new CareEngine(new Options(),new Random(1),start);Advance(e,50);e.Completed("rest",start.AddMinutes(50));Assert(e.MinutesFor("eyes")==0&&e.MinutesFor("posture")==0&&e.MinutesFor("rest")==0&&e.MinutesFor("water")==50,"rest completion linkage wrong");});
    Check("posture_completion_not_eye_break",()=>{CareEngine e=new CareEngine(new Options(),new Random(1),start);Advance(e,25);e.Completed("posture",start.AddMinutes(25));Assert(e.MinutesFor("eyes")==25&&e.MinutesFor("posture")==0&&e.MinutesFor("rest")==25,"posture counted as leaving seat");});
    Check("work_check_opt_in_and_settings_preserved",()=>{Options o=new Options{PetName="我的小猫",WorkStartCheck=true,WorkCheckDate="2026-10-27",NewsMinutes=15};CareCatalog.Normalize(o);Assert(o.PetName=="我的小猫"&&o.WorkStartCheck&&o.WorkCheckDate=="2026-10-27"&&o.NewsMinutes==15&&!new Options().WorkStartCheck,"unrelated preferences changed");});
    Check("eye_deadline_all_profiles",()=>{foreach(string profile in new[]{"轻声","适中","积极"})for(int seed=0;seed<50;seed++){Options o=new Options{Frequency=profile};CareEngine e=new CareEngine(o,new Random(seed),start);DateTime lastEye=start;bool saw=false;for(int step=1;step<=180*12;step++){DateTime now=start.AddSeconds(step*5);e.AddActive(5);var rules=e.Suggest(now);if(rules==null)continue;if(rules.Any(r=>r.Key=="eyes")){Assert((now-lastEye).TotalMinutes<=22.1,"eyes delayed by other prompts");lastEye=now;saw=true;}e.Ignored(now);}Assert(saw,"no eye prompt");}});
    Check("completion_keeps_ordinary_profile_spacing",()=>{Options o=Only("posture","water");o.Frequency="轻声";foreach(Rule r in o.Rules)r.Minutes=1;CareEngine e=new CareEngine(o,new Random(1),start);Advance(e,3);var first=e.Suggest(start.AddMinutes(3));Assert(first!=null,"first prompt missing");foreach(Rule r in first)e.Completed(r.Key,start.AddMinutes(3));Advance(e,2);Assert(e.Suggest(start.AddMinutes(5))==null,"completion bypasses quiet profile spacing");});
    Check("explicit_quiet_beats_eye_deadline",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,40);e.Busy(start.AddMinutes(40));Assert(e.Suggest(start.AddMinutes(60))==null,"eye deadline ignored explicit pause");});
    Check("eye_deadline_respects_feedback_buffer",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,40);e.Drank(start.AddMinutes(40));Assert(e.Suggest(start.AddMinutes(41))==null,"eye prompt ignores immediate feedback buffer");Assert(e.Suggest(start.AddMinutes(42))!=null,"overdue eyes not resumed");});
    Check("hourly_five_minute_rest_default",()=>Assert(new Options().Rules.First(r=>r.Key=="rest").Minutes==60&&Coach.DurationSeconds("rest")==300,"long rest defaults inconsistent"));
    Check("body_care_not_starved_by_eye_priority",()=>{foreach(string profile in new[]{"轻声","适中","积极"})for(int seed=0;seed<20;seed++){Options o=new Options{Frequency=profile};CareEngine e=new CareEngine(o,new Random(seed),start);var seen=new HashSet<string>();for(int step=1;step<=180*12;step++){DateTime now=start.AddSeconds(step*5);e.AddActive(5);var rules=e.Suggest(now);if(rules==null)continue;foreach(Rule r in rules)seen.Add(r.Key);e.Ignored(now);}Assert(seen.Contains("rest")&&seen.Contains("posture")&&seen.Contains("rest"),"eye priority starved body care");}});
    Check("multi_topic_input_only_uses_first_topic",()=>{Options o=new Options();o.CustomMessages["eyes"]="我的远眺提醒";string message=new CareText(o).Message(new List<Rule>{o.Rules.First(r=>r.Key=="eyes"),o.Rules.First(r=>r.Key=="posture")});Assert(message=="我的远眺提醒","multiple topics leaked into one reminder");});
    Check("auto_news_first_minute_without_click",()=>{Options o=new Options();o.ShareEnabled=false;AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);Assert(!clock.IsDue(start.AddSeconds(59))&&clock.IsDue(start.AddMinutes(1)),"automatic news tied to quote sharing or not due");});
    Check("auto_news_jitter_bounds",()=>{Options o=new Options();AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);for(int i=0;i<100;i++){clock.Consumed(start);double minutes=(clock.DueUtc-start).TotalMinutes;Assert(minutes>=8&&minutes<=12,"random interval out of range");}});
    Check("auto_news_fixed_interval",()=>{Options o=new Options{NewsJitter=false,NewsMinutes=5};AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);clock.Consumed(start);Assert(clock.DueUtc==start.AddMinutes(5),"fixed timing");});
    Check("auto_news_disabled",()=>{Options o=new Options{AutoNews=false};AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);Assert(!clock.IsDue(start.AddHours(1)),"disabled schedule");o.AutoNews=true;o.NewsEnabled=false;Assert(!clock.IsDue(start.AddHours(1)),"news disabled but scheduler runs");});
    Check("auto_news_no_backlog",()=>{Options o=new Options{NewsJitter=false};AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);clock.Consumed(start.AddHours(3));Assert(clock.DueUtc==start.AddHours(3).AddMinutes(10),"missed periods backfilled");});
    Check("auto_news_other_settings_keep_deadline",()=>{Options o=new Options();AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);DateTime due=clock.DueUtc;o.Tone="俏皮";clock.Reconfigure(start.AddSeconds(50));Assert(clock.DueUtc==due,"unrelated save delays news");});
    Check("auto_news_health_feedback_independent",()=>{Options o=new Options();AutoNewsClock clock=new AutoNewsClock(o,new Random(1),start);CareEngine e=new CareEngine(o,new Random(1),start);e.Rest(start.AddMinutes(2));e.Drank(start.AddMinutes(3));Assert(clock.IsDue(start.AddMinutes(4)),"health feedback changed news due");});
    Check("finance_guids_without_article_links",()=>{var items=ContentService.ParseNews("<rss><channel><title>金十数据</title><link>https://www.jin10.com/</link><item><title>One</title><guid>jin10:one</guid></item><item><title>Two</title><guid>jin10:two</guid></item></channel></rss>",NewsFeeds.Jin10,start);Assert(items.Count==2&&items[0].Id!=items[1].Id&&items.All(x=>x.SourceLinkOnly),"flash items collapsed or dropped");var pool=ContentService.Candidates(items,new[]{items[0].Id},false,start);Assert(pool.Count==1&&pool[0].Text=="Two","GUID based dedup failed");});
    Check("random_news_only_recent_unread",()=>{var items=new[]{new ContentItem{Id="old",Url="https://example.org/old",PublishedUtc=start.AddHours(-12)},new ContentItem{Id="seen",Url="https://example.org/seen",PublishedUtc=start.AddMinutes(-4)},new ContentItem{Id="new",Url="https://example.org/new",PublishedUtc=start.AddMinutes(-2)}};var pool=ContentService.Candidates(items,new[]{"seen"},true,start);Assert(pool.Count==1&&pool[0].Id=="new","old or seen news in random pool");});
    Check("combined_water_uses_rest_exercise",()=>{Options o=new Options();Assert(Buddy.ExerciseKey(new List<Rule>{o.Rules.First(r=>r.Key=="water"),o.Rules.First(r=>r.Key=="rest")})=="rest","wrong coach for water and walk");});
    Check("eyes_due_after_active_use",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,25);Assert(e.Suggest(start.AddMinutes(25))[0].Key=="eyes","not due");});
    Check("no_count_before_activity",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Assert(e.Suggest(start.AddHours(8))==null,"wall-clock alone triggered care");});
    Check("idle_buffer_does_not_fake_rest",()=>{CareEngine e=new CareEngine(Only("eyes","rest"),new Random(1),start);Advance(e,25);e.ResumeBuffer(start.AddMinutes(30));Assert(e.MinutesFor("eyes")==25&&e.MinutesFor("rest")==25,"idle discarded activity");});
    Check("screen_break_not_whole_body_break",()=>{CareEngine e=new CareEngine(Only("eyes","rest"),new Random(1),start);Advance(e,25);e.ScreenBreak(start.AddMinutes(30));Assert(e.MinutesFor("eyes")==0&&e.MinutesFor("rest")==25,"screen break erased walking need");});
    Check("drink_not_eye_rest",()=>{CareEngine e=new CareEngine(Only("eyes","water"),new Random(1),start);Advance(e,25);e.Drank(start.AddMinutes(25));Assert(e.MinutesFor("eyes")==25&&e.MinutesFor("water")==0,"incorrect drink reset");Assert(e.CooldownUntil<=start.AddMinutes(27),"drink blocks care");});
    Check("going_is_intention",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,25);e.Going(start.AddMinutes(25));Assert(e.MinutesFor("eyes")==25,"going counted as done");Assert(e.Suggest(start.AddMinutes(29))==null,"quiet ignored");});
    Check("ignore_not_hour_of_silence",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,25);e.Suggest(start.AddMinutes(25));e.Ignored(start.AddMinutes(26));Assert(e.BusyCount==0&&e.QuietUntil==DateTime.MinValue,"ignore counted as busy");Assert(e.CooldownUntil<=start.AddMinutes(35),"too long cooldown");});
    Check("explicit_busy_can_resume",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,25);e.Busy(start.AddMinutes(25));Assert(e.QuietUntil==start.AddMinutes(55),"first busy interval");e.Resume(start.AddMinutes(26));Assert(e.QuietUntil==DateTime.MinValue&&e.CooldownUntil==start.AddMinutes(28),"resume still muted");});
    Check("save_keeps_exposure",()=>{CareEngine e=new CareEngine(Only("eyes"),new Random(1),start);Advance(e,19);e.Reconfigure();Assert(e.MinutesFor("eyes")==19,"config erases exposure");});
    Check("completion_is_per_topic",()=>{CareEngine e=new CareEngine(Only("eyes","posture"),new Random(1),start);Advance(e,25);e.Completed("eyes",start.AddMinutes(25));Assert(e.MinutesFor("posture")==25&&e.MinutesFor("eyes")==0,"target completion resets other care");});
    Check("body_rest_does_not_fake_drinking",()=>{CareEngine e=new CareEngine(Only("eyes","water","posture"),new Random(1),start);Advance(e,25);e.Rest(start.AddMinutes(25));Assert(e.MinutesFor("water")==25&&e.MinutesFor("posture")==0,"rest updated drink");});
    Check("disabled_topics_stay_off",()=>{CareEngine e=new CareEngine(Only(),new Random(1),start);Advance(e,300);Assert(e.Suggest(start.AddMinutes(300))==null,"disabled care shown");});
    Check("all_health_wording",()=>{Options o=new Options();CareText words=new CareText(o);foreach(string tone in new[]{"温柔","俏皮","简短"}){o.Tone=tone;foreach(Rule r in o.Rules)for(int i=0;i<8;i++){string line=words.Message(new List<Rule>{r});Assert(!String.IsNullOrWhiteSpace(line),"empty wording");if(new[]{"eyes","posture","water"}.Contains(r.Key))Assert(!line.Contains("洗手间"),"new topic fell through to toilet");}}});
    Check("custom_long_wording_retained",()=>{Options o=new Options();string full=String.Concat(Enumerable.Repeat("很长的自定义提醒内容。",80));o.CustomMessages["eyes"]=full;Assert(new CareText(o).Message(new List<Rule>{o.Rules[0]})==full,"custom message truncated");});
    Check("rss_dates_and_links",()=>{string xml="<rss><channel><title>Test feed</title><item><title>&lt;b&gt;Title&lt;/b&gt;</title><link>https://example.org/a</link><pubDate>Tue, 27 Oct 2026 12:00:00 +0800</pubDate></item><item><title>No link</title></item><item><title>Bad</title><link>javascript:alert(1)</link></item></channel></rss>";var items=ContentService.ParseNews(xml,"https://example.org/rss",start);Assert(items.Count==1,"link filtering");Assert(items[0].Text=="Title","HTML not cleaned");Assert(items[0].PublishedUtc==new DateTime(2026,10,27,4,0,0,DateTimeKind.Utc),"RSS timezone");});
    Check("atom_and_relative_links",()=>{var items=ContentService.ParseNews("<feed xmlns='http://www.w3.org/2005/Atom'><title>Feed</title><entry><title>Entry</title><link href='/a'/><updated>2026-10-27T01:00:00Z</updated></entry></feed>","https://example.org/feed",start);Assert(items.Count==1&&items[0].Url=="https://example.org/a"&&items[0].PublishedUtc.HasValue,"Atom not parsed");});
    Check("dailyhot_json",()=>{var items=ContentService.ParseNews("{\"name\":\"DailyHot\",\"data\":[{\"title\":\"Title\",\"url\":\"https://example.org/a\"}]}","http://localhost:6688/ithome",start);Assert(items.Count==1&&!items[0].PublishedUtc.HasValue,"hot list date fabricated");});
    Check("xml_entities_rejected",()=>{bool rejected=false;try{ContentService.ParseNews("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///no-access'>]><rss><channel><title>&x;</title></channel></rss>","https://example.org/rss",start);}catch(System.Xml.XmlException){rejected=true;}Assert(rejected,"DTD accepted");});
    Check("quote_attribution",()=>{var item=ContentService.ParseQuote("{\"hitokoto\":\"Sample\",\"from\":\"Work\",\"from_who\":\"Author\",\"uuid\":\"abc\"}","文学",start);Assert(item.Source.Contains("Work")&&item.Source.Contains("Author")&&item.Url.EndsWith("abc"),"attribution lost");});
    Check("unsafe_urls_rejected",()=>Assert(!ContentService.SafeUrl("file:///c:/a")&&!ContentService.SafeUrl("javascript:alert(1)")&&!ContentService.SafeUrl("https://user:password@example.org/")&&ContentService.SafeUrl("http://localhost:6688/ithome"),"URL validation"));
    Check("offline_quote_fallback",()=>{ContentService service=new ContentService(folder);var first=service.QuoteAsync("诗词",false).Result;var second=service.QuoteAsync("诗词",false).Result;Assert(first.Source=="小歇原创短句"&&first.Text!=second.Text,"fallback falsely attributed or repeated");});
    if(args.Contains("--network")){
      Check("live_hitokoto",()=>{ContentService service=new ContentService(folder);var item=service.QuoteAsync("诗词",true).Result;Assert(item.Source.Contains("一言")&&item.Text.Length>0,"live quote unavailable, fallback used");});
      Check("live_ithome_rss",()=>{var items=ContentService.ParseNews(ContentService.Download("https://www.ithome.com/rss/"),"https://www.ithome.com/rss/",DateTime.UtcNow);Assert(items.Count>0&&items.All(x=>x.PublishedUtc.HasValue),"live feed parse");});
      Check("live_bbc_rss",()=>{var items=ContentService.ParseNews(ContentService.Download("https://feeds.bbci.co.uk/zhongwen/simp/rss.xml"),"https://feeds.bbci.co.uk/zhongwen/simp/rss.xml",DateTime.UtcNow);Assert(items.Count>0&&items.All(x=>x.PublishedUtc.HasValue),"live feed parse");});
      Check("live_jin10_relay",()=>{var items=ContentService.ParseNews(ContentService.Download(NewsFeeds.Jin10),NewsFeeds.Jin10,DateTime.UtcNow);Assert(items.Count>2&&items.All(x=>x.PublishedUtc.HasValue)&&items.Select(x=>x.Id).Distinct().Count()==items.Count,"Jin10 relay parse");});
      Check("live_wallstreet_relay",()=>{var items=ContentService.ParseNews(ContentService.Download(NewsFeeds.Wallstreet),NewsFeeds.Wallstreet,DateTime.UtcNow);Assert(items.Count>2&&items.All(x=>x.PublishedUtc.HasValue),"Wallstreet relay parse");});
    }
    string report=Path.Combine(folder,"report.json");File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{Passed=passed,Failed=failed,PassedCount=passed.Count,FailedCount=failed.Count}));Console.WriteLine("Passed: "+passed.Count+"; Failed: "+failed.Count);foreach(string error in failed)Console.WriteLine(error);return failed.Count==0?0:1;
  }
}
